### **3. Rust Core Drag Algorithm** [compose/rs/lib.rs](compose/rs/lib.rs#L6461-L6540)

Identical logic to TypeScript, but also returns `DiffUpdate` structs:

```rust
pub fn drag_pieces_in_design(
    design_pieces: &[Piece],
    design_connections: &[Connection],
    selected_pieces: &[Piece],
    offset: &Coord,
) -> DesignDiff {
    let selected_guids: HashSet<&str> =
        selected_pieces.iter().map(|p| p.guid.as_str()).collect();

    // Build parent map (child_guid -> (connection_guid, parent_guid))
    let mut parent_map: HashMap<&str, (&str, &str)> = HashMap::new();
    for conn in design_connections {
        let connecting_guid = conn.connecting.piece.guid.as_str();
        let connected_guid = conn.connected.piece.guid.as_str();
        parent_map.insert(connecting_guid, (conn.guid.as_str(), connected_guid));
    }

    // Fixed pieces = selected pieces with no parent connection
    let fixed_guids: HashSet<&str> = selected_guids
        .iter()
        .filter(|&&guid| !parent_map.contains_key(guid))
        .copied()
        .collect();

    // Move fixed pieces' centers by offset
    let piece_updates: Vec<DiffUpdate<PieceDiff>> = fixed_guids
        .iter()
        .filter_map(|&guid| {
            let center = piece_map.get(guid)?.center.as_ref()?;
            Some(DiffUpdate {
                key: "piece".to_string(),
                guid: guid.to_string(),
                diff: PieceDiff {
                    center: Some(Some(Coord {
                        u: center.u + offset.u,
                        v: center.v + offset.v,
                    })),
                    ..Default::default()
                },
            })
        })
        .collect();

    // Move connected pieces' parent connection u/v by offset
    let connection_updates: Vec<DiffUpdate<ConnectionDiff>> = selected_guids
        .iter()
        .filter(|&&guid| {
            // Exclude fixed pieces and pieces with selected ancestors
            if fixed_guids.contains(guid) { return false; }
            // Walk up parent chain - if finds selected ancestor, skip
            parent_map.contains_key(guid)
        })
        .map(|&guid| {
            let (conn_guid, _parent_guid) = parent_map[guid];
            DiffUpdate {
                guid: conn_guid.to_string(),
                diff: ConnectionDiff {
                    u: Some(Some(offset.u)),
                    v: Some(Some(offset.v)),
                    ..Default::default()
                },
            }
        })
        .collect();

    // Build and return the DesignDiff
    let mut diff = DesignDiff { ..Default::default() };
    if !piece_updates.is_empty() {
        diff.pieces = Some(CollectionDiff { updated: Some(piece_updates), ..Default::default() });
    }
    if !connection_updates.is_empty() {
        diff.connections = Some(CollectionDiff { updated: Some(connection_updates), ..Default::default() });
    }
    diff
}
```

