// Fixed-point propagation: cascade non-default statuses between pieces and connections.
// A connection with a non-default endpoint piece becomes "modified".
// A piece that is an endpoint of a non-default connection becomes "modified".
// Repeat until no more changes (handles multi-hop cascades like drag → connection → child piece → child connection).
if (designDiff) {
  let changed = true;
  while (changed) {
    changed = false;
    for (const line of lineMap.values()) {
      if (line.status === "default") {
        const src = pointMap.get(line.connection.connected.piece.guid);
        const tgt = pointMap.get(line.connection.connecting.piece.guid);
        if ((src && src.status !== "default") || (tgt && tgt.status !== "default")) {
          (line as { status: DiagramEntityStatus }).status = "modified";
          changed = true;
        }
      }
      if (line.status !== "default") {
        const src = pointMap.get(line.connection.connected.piece.guid);
        if (src && src.status === "default") {
          src.status = "modified";
          changed = true;
        }
        const tgt = pointMap.get(line.connection.connecting.piece.guid);
        if (tgt && tgt.status === "default") {
          tgt.status = "modified";
          changed = true;
        }
      }
    }
  }
}

