tool_input.newString:
if (visualPositions.size > 0) {
  applyDragPreviewPositions(visualPositions);
  // Only mark pieces that were actually changed by the drag diff as dragging.
  // dragDiff.pieces.updated contains fixed pieces whose centers moved;
  // dragDiff.connections.updated contains connections whose child pieces moved.
  // Do NOT mark all pieces from piecesMetadata — that turns the entire design yellow.
  if (designStore) {
    const draggedPieceGuids = new Set<string>();
    for (const pu of dragDiff.pieces?.updated ?? []) {
      if (pu.piece?.guid) draggedPieceGuids.add(pu.piece.guid);
    }
    for (const cu of dragDiff.connections?.updated ?? []) {
      const connGuid = (cu as any).connection?.guid;
      if (connGuid) {
        // Find the connection in the flat design to get its endpoint pieces
        const conn = previewFlatDesign.connections?.find((c: any) => c.guid === connGuid);
        if (conn) {
          if (conn.connecting?.piece?.guid) draggedPieceGuids.add(conn.connecting.piece.guid);
        }
      }
    }
    designStore.setDraggingPieces(draggedPieceGuids);
  }
}

